sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  $scope.week     = 0;      // 0 = this week, 1 = next week
  $scope.dayYmd   = '';     // selected day, empty = no day filter
  $scope.typeVal  = '';
  $scope.selected = null;   // workspace shown in the detail panel

  $scope.visibleDays = [];
  $scope.filtered    = [];
  $scope.shown       = [];
  $scope.showAll     = false;

  var PAGE = 8;

  function recompute() {
    // Any filter change closes the detail panel.
    $scope.selected = null;

    var offset = $scope.week * 5;
    $scope.visibleDays = $scope.data.days.slice(offset, offset + 5);

    var dayIdx = -1;
    if ($scope.dayYmd) {
      for (var i = 0; i < $scope.data.days.length; i++) {
        if ($scope.data.days[i].ymd === $scope.dayYmd) {
          dayIdx = i;
          break;
        }
      }
    }

    var out = [];
    var list = $scope.data.workspaces;

    for (var j = 0; j < list.length; j++) {
      var w = list[j];

      if ($scope.typeVal && w.typeVal !== $scope.typeVal) continue;
      if (dayIdx > -1 && w.days[dayIdx] !== 'free') continue;

      w.viewStrip = w.days.slice(offset, offset + 5);

      var free = 0;
      for (var k = 0; k < w.viewStrip.length; k++) {
        if (w.viewStrip[k] === 'free') free++;
      }
      w.viewFree = free;

      out.push(w);
    }

    $scope.filtered = out;
    $scope.shown = $scope.showAll ? out : out.slice(0, PAGE);
  }

  $scope.setWeek = function(n) {
    $scope.week = n;
    $scope.dayYmd = '';
    recompute();
  };

  $scope.toggleDay = function(ymd) {
    $scope.dayYmd = ($scope.dayYmd === ymd) ? '' : ymd;
    recompute();
  };

  $scope.setType = function(v) {
    $scope.typeVal = v;
    recompute();
  };

  $scope.clearFilters = function() {
    $scope.typeVal = '';
    $scope.dayYmd  = '';
    recompute();
  };

  $scope.toggleAll = function() {
    $scope.showAll = !$scope.showAll;
    $scope.shown = $scope.showAll
                 ? $scope.filtered
                 : $scope.filtered.slice(0, PAGE);
  };

  // Book link for a whole run, carrying the workspace and dates.
  // The catalog item's onLoad script reads these back out.
  $scope.runUrl = function(w, run) {
    return $scope.data.bookBase +
           '&wrm_ws=' + w.sysId +
           '&wrm_ws_label=' + encodeURIComponent(w.name) +
           '&wrm_start=' + encodeURIComponent(run.startYmd + ' 09:00:00') +
           '&wrm_end='   + encodeURIComponent(run.endYmd   + ' 17:00:00');
  };

  // Book link with no dates, for the panel's main button.
  $scope.spaceUrl = function(w) {
    return $scope.data.bookBase +
           '&wrm_ws=' + w.sysId +
           '&wrm_ws_label=' + encodeURIComponent(w.name);
  };

  $scope.open = function(w) {
    $scope.selected = w;

    // Bring the panel into view — it renders above the grid.
    setTimeout(function() {
      var el = document.querySelector('.wrm-wk-detail');
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 50);
  };

  $scope.close = function() {
    $scope.selected = null;
  };

  recompute();
};

sp_widget.css:
.wrm-wk-head { display: flex; align-items: center; gap: 14px; margin-bottom: 14px; }
.wrm-wk-head h2 { margin: 0; font-size: 22px; color: var(--ink); }
.wrm-wk-toggle { margin-left: auto; display: flex; gap: 6px; }
.wrm-wk-toggle button {
  font-size: 12px; padding: 6px 14px; border: 1px solid var(--line);
  background: var(--surface); color: var(--ink-2);
  border-radius: var(--r-pill); cursor: pointer;
}
.wrm-wk-toggle button.on { background: var(--ink); border-color: var(--ink); color: var(--paper); }
.wrm-wk-bar { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; margin-bottom: 12px; }
.wrm-wk-day {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--r-soft); padding: 10px 8px; text-align: center; cursor: pointer;
}
.wrm-wk-day .lbl { display: block; font-size: 10px; letter-spacing: .07em; color: var(--ink-3); }
.wrm-wk-day .num { display: block; font-size: 20px; line-height: 1.3; color: var(--ink); }
.wrm-wk-day .sub { display: block; font-size: 10px; color: var(--ink-3); }
.wrm-wk-day.today { border-color: var(--ink-3); }
.wrm-wk-day.on { background: var(--clay); border-color: var(--clay); }
.wrm-wk-day.on .lbl, .wrm-wk-day.on .num, .wrm-wk-day.on .sub { color: var(--on-clay); }
.wrm-wk-pills { display: flex; gap: 7px; flex-wrap: wrap; margin-bottom: 8px; }
.wrm-wk-pills button {
  font-size: 12px; padding: 6px 14px; border: 1px solid var(--line);
  background: var(--surface); color: var(--ink-2);
  border-radius: var(--r-pill); cursor: pointer;
}
.wrm-wk-pills button.on { background: var(--ink); border-color: var(--ink); color: var(--paper); }
.wrm-wk-count { font-size: 12px; color: var(--ink-3); margin: 12px 0; }
.wrm-wk-count .clear {
  background: none; border: 0; color: var(--clay);
  font-size: 12px; cursor: pointer; padding: 0 0 0 10px;
}
/* ---------- detail panel ---------- */
.wrm-wk-detail {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-card);
  padding: 18px 20px;
  margin: 14px 0 4px;
}
.wrm-wk-detail .close {
  position: absolute; top: 10px; right: 12px;
  background: none; border: 0; font-size: 22px; line-height: 1;
  color: var(--ink-3); cursor: pointer; padding: 4px 8px;
}
.wrm-wk-detail .close:hover { color: var(--ink); }
.dl-top { display: flex; gap: 18px; flex-wrap: wrap; }
.dl-img {
  width: 200px; height: 130px; flex: none;
  background: var(--surface-2); border-radius: var(--r-soft); overflow: hidden;
}
.dl-img img { width: 100%; height: 100%; object-fit: cover; }
.dl-info { flex: 1; min-width: 240px; }
.dl-name { font-size: 19px; color: var(--ink); }
.dl-sub { font-size: 12px; color: var(--ink-3); margin: 3px 0 10px; }
.dl-tags { display: flex; gap: 7px; flex-wrap: wrap; margin-bottom: 10px; }
.dl-tags .tag {
  font-size: 11px; padding: 4px 11px;
  background: var(--surface-2); color: var(--ink-2);
  border-radius: var(--r-pill);
}
.dl-tags .tag.maint { background: var(--out-bg); color: var(--out-fg); }
.dl-desc { font-size: 13px; color: var(--ink-2); margin: 0 0 12px; }
.dl-book {
  display: inline-block;
  font-size: 13px; font-weight: 500;
  background: var(--clay); color: var(--on-clay);
  padding: 9px 20px; border-radius: var(--r-pill);
  text-decoration: none;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.22);
}
.dl-book:hover, .dl-book:focus { background: var(--clay-press); color: var(--on-clay); text-decoration: none; }

/* Fully-booked state: same shape as the book button, visibly inert. */
.dl-book.off {
  background: var(--surface-2);
  color: var(--ink-3);
  box-shadow: inset 0 0 0 1px var(--line);
  cursor: not-allowed;
  pointer-events: none;
}

/* ---------- free runs ---------- */
.dl-runs { margin-top: 18px; border-top: 1px solid var(--line); padding-top: 14px; }
.dl-runs-head {
  font-size: 10px; letter-spacing: .08em; color: var(--ink-3);
  margin-bottom: 11px; text-transform: uppercase;
}
.dl-run {
  display: flex; align-items: center; gap: 14px;
  padding: 9px 0;
  border-bottom: 1px solid var(--line);
}
.dl-run:last-child { border-bottom: 0; }
.dl-run .rail { width: 170px; flex: none; }
.dl-run .rail .ends {
  display: flex; justify-content: space-between;
  font-size: 10px; letter-spacing: .07em; color: var(--ink-3);
  margin-bottom: 4px;
}
.dl-run .rail .line { display: flex; align-items: center; gap: 6px; }
.dl-run .rail .dot { width: 6px; height: 6px; border-radius: 50%; flex: none; }
.dl-run .rail .dot.start { background: var(--clay); }
.dl-run .rail .dot.end { border: 1px solid var(--clay); }
.dl-run .rail .track { flex: 1; height: 2px; background: var(--line); border-radius: 2px; }
.dl-run .len { flex: 1; font-size: 13px; color: var(--ink); }
.dl-run .go {
  font-size: 11px; background: var(--clay); color: var(--on-clay);
  padding: 6px 15px; border-radius: var(--r-pill);
  text-decoration: none; white-space: nowrap; flex: none;
}
.dl-run .go:hover { background: var(--clay-press); color: var(--on-clay); text-decoration: none; }
.dl-none { font-size: 13px; color: var(--ink-3); padding: 6px 0; }
/* ---------- card grid ---------- */
.wrm-wk-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 12px; }
.wrm-wk-card {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--r-soft); overflow: hidden; cursor: pointer;
}
.wrm-wk-card:hover { border-color: var(--ink-3); }
.wrm-wk-card.sel { border-color: var(--clay); }
.wrm-wk-card.dim { opacity: .62; }
.wrm-wk-card .thumb { height: 62px; background: var(--surface-2); }
.wrm-wk-card .thumb img { width: 100%; height: 100%; object-fit: cover; }
.wrm-wk-card .body { padding: 12px 13px; }
.wrm-wk-card .nm { font-size: 14px; color: var(--ink); }
.wrm-wk-card .sub { font-size: 11px; color: var(--ink-3); margin: 2px 0 10px; }
.wrm-wk-card .strip { display: flex; gap: 4px; }
.wrm-wk-card .strip span { flex: 1; height: 20px; border-radius: 3px; }
.wrm-wk-card .strip span.free  { background: var(--free-bg); }
.wrm-wk-card .strip span.taken { background: var(--held-bg); }
.wrm-wk-card .strip span.maint { background: var(--out-bg); }
.wrm-wk-card .foot { margin-top: 11px; }
.wrm-wk-card .note { font-size: 11px; color: var(--out-fg); }
.wrm-wk-card .note.free { color: var(--free-fg); }
.wrm-wk-more { text-align: center; margin-top: 14px; }
.wrm-wk-more button {
  font-size: 13px; padding: 9px 22px;
  background: transparent; color: var(--ink-2);
  border: 1px solid var(--line); border-radius: var(--r-pill);
  cursor: pointer;
}
.wrm-wk-more button:hover { background: var(--surface-2); color: var(--ink); }
.wrm-wk-empty {
  text-align: center; padding: 38px 20px;
  background: var(--surface); border: 1px dashed var(--line);
  border-radius: var(--r-card); color: var(--ink-2);
}
.wrm-wk-empty h3 { margin: 0 0 6px; font-size: 17px; color: var(--ink); }
.wrm-wk-empty p { margin: 0; font-size: 13px; }

sp_widget.script:
(function() {

  var WEEKDAYS = ['SUN','MON','TUE','WED','THU','FRI','SAT'];
  var MONTHS   = ['JAN','FEB','MAR','APR','MAY','JUN',
                  'JUL','AUG','SEP','OCT','NOV','DEC'];

  // Reservation statuses that actually hold a workspace.
  var HOLDING = 'pending_check_in,checked_in';

  // The catalog item users book through.
  var CAT_ITEM = 'fe1e919e93c6c3108c8874dcebba10d0';

  // How far ahead the detail panel looks.
  var HORIZON_DAYS = 30;

  // --- 1. The ten weekday tiles for the browse grid ---

  var todayYmd = new GlideDateTime().getDisplayValue().split(' ')[0];
  var tp = todayYmd.split('-');
  var todayUtc = Date.UTC(+tp[0], +tp[1] - 1, +tp[2]);

  // Step back to Monday. getUTCDay: 0 = Sunday.
  var dow = new Date(todayUtc).getUTCDay();
  var backToMonday = (dow === 0) ? 6 : (dow - 1);
  var mondayUtc = todayUtc - (backToMonday * 86400000);

  function ymd(ms) {
    var d = new Date(ms);
    var m = d.getUTCMonth() + 1;
    var day = d.getUTCDate();
    return d.getUTCFullYear() + '-' +
           (m < 10 ? '0' + m : m) + '-' +
           (day < 10 ? '0' + day : day);
  }

  function label(ms) {
    var d = new Date(ms);
    return {
      weekday: WEEKDAYS[d.getUTCDay()],
      dayNum:  ('0' + d.getUTCDate()).slice(-2),
      month:   MONTHS[d.getUTCMonth()]
    };
  }

  var days = [];   // ten weekday entries for the browse grid
  for (var w = 0; w < 2; w++) {
    for (var i = 0; i < 5; i++) {
      var ms = mondayUtc + ((w * 7 + i) * 86400000);
      var lb = label(ms);
      days.push({
        ymd:     ymd(ms),
        weekday: lb.weekday,
        dayNum:  lb.dayNum,
        month:   lb.month,
        isToday: ymd(ms) === todayYmd,
        free:    0
      });
    }
  }

  // --- 2. The 30-day horizon used for free runs ---

  var horizon = [];
  for (var h = 0; h < HORIZON_DAYS; h++) {
    var hms = todayUtc + (h * 86400000);
    var hd  = new Date(hms).getUTCDay();
    horizon.push({
      ms:        hms,
      ymd:       ymd(hms),
      isWeekend: (hd === 0 || hd === 6)
    });
  }

  var windowStart = horizon[0].ymd;
  var windowEnd   = horizon[horizon.length - 1].ymd;
  // The browse grid may start before today, so widen the lower bound.
  if (days[0].ymd < windowStart) windowStart = days[0].ymd;

  // Mark every day from sYmd to eYmd inclusive as held for a workspace.
  function markHeld(store, wsId, sYmd, eYmd) {
    if (!wsId || !sYmd || !eYmd) return;
    if (eYmd < windowStart || sYmd > windowEnd) return;

    if (!store[wsId]) store[wsId] = {};

    var sP = sYmd.split('-');
    var eP = eYmd.split('-');
    var cur = Date.UTC(+sP[0], +sP[1] - 1, +sP[2]);
    var end = Date.UTC(+eP[0], +eP[1] - 1, +eP[2]);

    while (cur <= end) {
      store[wsId][ymd(cur)] = true;
      cur += 86400000;
    }
  }

  // --- 3. Which workspaces are held on which days ---

  var held = {};   // { workspaceSysId: { 'YYYY-MM-DD': true } }

  // 3a. Approved reservations that produced a tracker record.
  var res = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
  res.addQuery('reservation_status', 'IN', HOLDING);
  res.query();

  while (res.next()) {
    var sDisp = res.getDisplayValue('work_start');
    var eDisp = res.getDisplayValue('work_end');
    if (!sDisp || !eDisp) continue;

    markHeld(held, res.getValue('workspace'),
             sDisp.split(' ')[0], eDisp.split(' ')[0]);
  }

  // 3b. Requests still awaiting approval hold their dates too. They have
  // no tracker record yet, so read the dates off the RITM variables.
  // Without this, a space looks free on days someone has already asked for.
  var ritm = new GlideRecord('sc_req_item');
  ritm.addQuery('cat_item', CAT_ITEM);
  ritm.addQuery('active', true);
  ritm.query();

  while (ritm.next()) {
    var rWs = '', rStart = '', rEnd = '';
    try {
      rWs    = ritm.variables.select_workspace.toString();
      rStart = ritm.variables.start_date_time.getDisplayValue();
      rEnd   = ritm.variables.end_date_time.getDisplayValue();
    } catch (err) {
      gs.warn('WRM week: RITM variable read failed - ' + err);
      continue;
    }
    if (!rWs || !rStart || !rEnd) continue;

    markHeld(held, rWs, rStart.split(' ')[0], rEnd.split(' ')[0]);
  }

  // --- 4. Build the workspace rows ---

  data.workspaces = [];
  var typeSet = {};

  var gr = new GlideRecord('x_1903615_worksp_0_workspace_options');
  gr.addQuery('status', '!=', 'decommissioned');
  gr.orderBy('workspace_name');
  gr.query();

  while (gr.next()) {
    var id      = gr.getUniqueValue();
    var status  = gr.getValue('status');
    var typeVal = gr.getValue('workspace_type');
    var typeLbl = gr.getDisplayValue('workspace_type');

    // Maintenance keeps its own visual treatment. Anything else that
    // isn't 'available' - unavailable, undergoing_approval - is simply
    // not bookable, so it must not render as free.
    var isMaint    = status === 'under_maintenance';
    var isBookable = status === 'available';

    if (typeVal) typeSet[typeVal] = typeLbl;

    var raw = gr.getValue('image');
    var url = '';
    if (raw) {
      url = raw.indexOf('.') > -1
          ? (raw.charAt(0) === '/' ? raw : '/' + raw)
          : '/sys_attachment.do?sys_id=' + raw;
    }

    // States for the ten browse-grid days.
    var dayStates = [];
    for (var k = 0; k < days.length; k++) {
      var state;
      if (isMaint) {
        state = 'maint';
      } else if (!isBookable) {
        state = 'taken';
      } else if (held[id] && held[id][days[k].ymd]) {
        state = 'taken';
      } else {
        state = 'free';
      }
      if (state === 'free') days[k].free++;
      dayStates.push(state);
    }

    // Runs of consecutive free days across the 30-day horizon.
    // Weekends don't break a run - a booking that spans a weekend
    // is one booking - but they don't count as working days.
    // Only bookable spaces get runs at all.
    var runs = [];
    if (isBookable) {
      var open = null;
      for (var n = 0; n < horizon.length; n++) {
        var hDay = horizon[n];
        var taken = held[id] && held[id][hDay.ymd];

        if (!taken) {
          if (!open) {
            open = { startMs: hDay.ms, endMs: hDay.ms, working: 0 };
          } else {
            open.endMs = hDay.ms;
          }
          if (!hDay.isWeekend) open.working++;
        } else if (open) {
          runs.push(open);
          open = null;
        }
      }
      if (open) runs.push(open);
    }

    // Trim trailing weekend days so a run doesn't end on a Sunday.
    var runOut = [];
    for (var r = 0; r < runs.length; r++) {
      var rn = runs[r];
      if (rn.working === 0) continue;   // weekend-only stretch

      while (new Date(rn.endMs).getUTCDay() === 0 ||
             new Date(rn.endMs).getUTCDay() === 6) {
        rn.endMs -= 86400000;
      }
      while (new Date(rn.startMs).getUTCDay() === 0 ||
             new Date(rn.startMs).getUTCDay() === 6) {
        rn.startMs += 86400000;
      }

      var sl = label(rn.startMs);
      var el = label(rn.endMs);
      var single = rn.startMs === rn.endMs;

      runOut.push({
        startYmd:  ymd(rn.startMs),
        endYmd:    ymd(rn.endMs),
        startLbl:  sl.weekday + ' ' + sl.dayNum + ' ' + sl.month,
        endLbl:    el.weekday + ' ' + el.dayNum + ' ' + el.month,
        single:    single,
        isToday:   ymd(rn.startMs) === todayYmd,
        working:   rn.working,
        lengthLbl: rn.working === 1 ? '1 working day'
                                    : rn.working + ' working days'
      });
    }

    data.workspaces.push({
      sysId:       id,
      name:        gr.getDisplayValue('workspace_name'),
      typeVal:     typeVal,
      typeLabel:   typeLbl,
      location:    gr.getDisplayValue('location'),
      capacity:    gr.getValue('max_occupancy'),
      description: gr.getValue('workspace_description'),
      imageUrl:    url,
      maint:       isMaint,
      // No runs means nothing to book: either the space isn't available,
      // or every day in the horizon is already held.
      bookable:    isBookable && runOut.length > 0,
      days:        dayStates,
      runs:        runOut
    });
  }

  data.days = days;

  // --- 5. Filter pill options ---

  data.types = [];
  for (var t in typeSet) {
    data.types.push({ value: t, label: typeSet[t] });
  }
  data.types.sort(function(a, b) { return a.label < b.label ? -1 : 1; });

  // Catalog item to book against. The client appends the workspace
  // and dates, which the item's onLoad script reads.
  data.bookBase = '?id=sc_cat_item&sys_id=' + CAT_ITEM;

})();
